@using sv_4d6d5857efde4ea1b10c6f6e54608e86.Services

<div class="message-area">
    <div class="message-area-header">
        <h2># @Channel.Name</h2>
        <p>@Channel.Description</p>
    </div>

    <div class="message-list" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }
        @if (HasMoreMessages)
        {
            <button class="load-more-btn" @onclick="() => OnLoadMore.InvokeAsync()">
                Load older messages
            </button>
        }
        @foreach (var message in Messages)
        {
            var threadInfo = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == message.Id);
            <MessageItem Message="message"
                         IsThreadStarter="threadInfo is not null"
                         ReplyCount="threadInfo?.ReplyCount ?? 0"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                  ButtonLabel="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public bool HasMoreMessages { get; set; } = true;
    [Parameter] public EventCallback<Message> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private Task HandleScroll()
    {
        // Scroll-to-top detection is handled via JS interop in production;
        // the Load More button provides a fallback.
        return Task.CompletedTask;
    }
}

