arguments.file_text:
@page "/chat"
@using sv_4d6d5857efde4ea1b10c6f6e54608e86.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        @if (channels is not null)
        {
            <ChannelList Channels="channels"
                         SelectedChannelId="selectedChannel?.Id ?? 0"
                         OnChannelSelected="SelectChannel" />
        }
    </div>

    <div class="chat-main @(threadRootMessage is null ? "full-width" : "")">
        @if (selectedChannel is not null)
        {
            <MessageArea Channel="selectedChannel"
                         Messages="messages"
                         ThreadSummaries="threadSummaries"
                         IsLoadingMore="isLoadingMore"
                         HasMoreMessages="hasMoreMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         IsLoading="isThreadLoading"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel>? channels;
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    // Thread state
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];
    private bool isThreadLoading;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = [];
        threadSummaries = [];
        hasMoreMessages = true;

        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        hasMoreMessages = messages.Count >= PageSize;
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channels to update unread counts
        channels = await ChatService.GetChannelsAsync();

        // Build thread summaries from messages that have replies
        await BuildThreadSummaries();
    }

    private async Task LoadMoreMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;

        isLoadingMore = true;
        var olderMessages = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        hasMoreMessages = olderMessages.Count >= PageSize;
        messages.InsertRange(0, olderMessages);
        isLoadingMore = false;

        await BuildThreadSummaries();
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;

        var newMessage = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(newMessage);
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Refresh messages to show updated reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messages.Count);
        }
    }

    private async Task OpenThread(Message rootMessage)
    {
        threadRootMessage = rootMessage;
        isThreadLoading = true;
        threadReplies = [];

        var thread = await ChatService.GetThreadAsync(rootMessage.Id);
        // Exclude the root message itself from replies
        threadReplies = thread.Where(m => m.Id != rootMessage.Id).ToList();
        isThreadLoading = false;
    }

    private void CloseThread()
    {
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannel is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        await BuildThreadSummaries();
    }

    private async Task BuildThreadSummaries()
    {
        // Identify thread starters: messages that other messages reply to
        var rootIds = messages
            .Where(m => m.ReplyToId is not null)
            .Select(m => m.ReplyToId!.Value)
            .Distinct()
            .ToList();

        var summaries = new List<ThreadSummary>();
        foreach (var rootId in rootIds)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            var replies = thread.Where(m => m.Id != rootId).ToList();
            if (replies.Count > 0)
            {
                summaries.Add(new ThreadSummary(rootId, replies.Count, replies.Max(r => r.SentAt)));
            }
        }

        threadSummaries = summaries;
    }
}

