+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+::deep .close-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+::deep .thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+    background: #2f3136;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+::deep .thread-reply {
+    padding: 8px 0;
+    border-bottom: 1px solid #2f3136;
+}
+
+/* No channel selected */
+.no-channel-selected {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    height: 100%;
+    color: #8e9297;
+    font-size: 1.1rem;
+}
